#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, U;
    cin >> N >> K >> U;

    vector<int> position(U + 1);
    vector<vector<int>> cards(N, vector<int>(K));

    for (auto& card : cards)
        for (int& x : card)
            cin >> x;

    for (int i = 1, x; i <= U; ++i) {
        cin >> x;
        position[x] = i;
    }

    int earliest = U + 1;
    vector<int> winners;

    for (int i = 0; i < N; ++i) {
        int completion = 0;
        for (int x : cards[i])
            completion = max(completion, position[x]);

        if (completion < earliest) {
            earliest = completion;
            winners.clear();
            winners.push_back(i + 1);
        } else if (completion == earliest) {
            winners.push_back(i + 1);
        }
    }

    for (int i = 0; i < (int)winners.size(); ++i) {
        if (i) cout << ' ';
        cout << winners[i];
    }
    cout << '\n';

    return 0;
}
